        AND business_type = #{businessType}


        AND business_id = #{businessId}


        AND applicant_id = #{applicantId}


        AND current_stage_id = #{currentStageId}


        AND status = #{status}


        AND status != #{statusNotEqual}


        AND status IN

            #{statusValue}



        AND parent_instance_id = #{parentInstanceId}


        AND parent_instance_id IS NULL


        AND parent_task_id = #{parentTaskId}


        AND root_instance_id = #{rootInstanceId}


        AND sub_workflow_approver_ids = #{subWorkflowApproverIds}


ORDER BY create_time DESC

